from prep import *
E=rd('onboarding-en.json');D=rd('onboarding-da.json')
E['openingText']=rd('modern-en.json')['chapters'][0]['paragraphs'][0]
E['about']=E['about'].replace('He published it in 1922 in Paris because no Anglophone publisher would touch it; it was banned for obscenity in the United States until 1934 and in the United Kingdom until 1936.','Sylvia Beach published it in Paris in 1922. An American court ruling in 1933 cleared the way for the authorised US edition in 1934; the first British edition appeared in 1936.').replace('Joyce gave each of its eighteen episodes a distinct hour, location, organ of the body, and prose technique.','Joyce developed schemes linking its eighteen episodes with locations, times, bodily organs and narrative techniques; not every category applies to every episode.').replace('Ulysses is the founding work of literary modernism and the most ambitious novel in English.','Ulysses is a major work of literary modernism and an unusually ambitious experiment in the English-language novel.').replace('parodies of every prose style','parodies of prose styles')
D['about']='Torsdag den 16. juni 1904 steger Leopold Bloom en nyre til morgenmad. Han sælger annonceplads i Dublin, og i løbet af dagen når han både en begravelse, en tur forbi avisredaktionen og en gorgonzolasandwich hos Davy Byrne. I samme by underviser den unge Stephen Dedalus i historie. Han sørger over sin mor. Sent på aftenen følges de to mænd ad, og da de når Blooms køkken, laver Bloom kakao. Bogens sidste ord tilhører Molly Bloom, der ligger vågen ved siden af sin mand.\n\nJoyce skrev Ulysses mellem 1914 og 1921 i Trieste, Zürich og Paris. Sylvia Beach udgav romanen i Paris i 1922. En amerikansk domstolsafgørelse i 1933 banede vejen for den autoriserede amerikanske udgave i 1934; den første britiske udgave kom i 1936. Romanen trækker på Homers Odysseen: Bloom svarer til Odysseus, Stephen til Telemachos og Molly til Penelope. Joyce udarbejdede skemaer, som forbinder de atten episoder med blandt andet steder, tidspunkter, kropsorganer og fortælleteknikker. Ikke alle kategorier gælder for hver episode.\n\nUlysses er et hovedværk i den litterære modernisme og et usædvanligt ambitiøst eksperiment med romanformen. Den rummer indre monolog, avisoverskrifter og parodier på stilarter fra angelsaksisk til victoriansk prosa. Et kapitel består af spørgsmål og svar, et andet ligner et skuespil. Dublin beskrives så detaljeret, at Joyce hævdede, at byen kunne genopbygges ud fra bogen, hvis den blev ødelagt. Romanen viser, hvor meget en almindelig bevidsthed kan rumme: sult, begær, sorg, erindringer og tanker, der vandrer. En annoncesælgers torsdag bliver lige så værd at følge som en konges hjemkomst.'
E['cast'][0]['description']=E['cast'][0]['description'].replace('have not slept together fully since','have not had full sexual intercourse since').replace('mildly cuckolded','aware of his wife’s affair').replace('for most of fourteen hours','through much of the day and into the night')
D['cast'][0]['description']='En otteogtrediveårig annonceagent fra Dublin med ungarsk‑jødiske rødder. Hans søn Rudy døde elleve dage gammel, elleve år før romanens handling, og han og Molly har ikke haft fuldt samleje siden. Han er nysgerrig, venlig og optaget af videnskab. Han ved, at hans kone har en affære, og han bærer på en stille sorg. Han kan lide indmad og går med en kartoffel i lommen. Romanen følger hans tanker gennem en stor del af dagen og ind i natten og finder en form for heltemod i hans opmærksomhed på andre.'
E['cast'][1]['description']=E['cast'][1]['description'].replace('A twenty-two-year-old schoolteacher, occasional poet, and former seminarian, returned from a year in Paris when his mother fell ill and refused to pray at her deathbed.','A twenty-two-year-old schoolteacher and aspiring writer. Educated by Jesuits, he rejected a religious vocation. He returned from Paris when his mother fell ill and refused to pray at her deathbed.')
D['cast'][1]['description']='En toogtyveårig skolelærer og forfatterspire. Han gik i skole hos jesuitterne, men afviste at blive præst. Han vendte hjem fra Paris, da hans mor blev syg, og nægtede at bede ved hendes dødsleje. Vi møder ham også i Joyces tidligere roman Portræt af kunstneren som ungt menneske. Han er begavet, stolt, veltalende, uden penge og åndeligt hjemløs. Som Telemachos søger han en faderskikkelse, han ikke helt kan sætte navn på. Hans egen far, den drikfældige og sentimentale Simon Dedalus, dukker stadig op i den by, Stephen forsøger at forlade.'
E['cast'][2]['description']=E['cast'][2]['description'].replace('to a Spanish-Jewish mother and an Irish father','to Lunita Laredo and an Irish soldier, Major Tweedy').replace('eight unpunctuated sentences across forty-five pages','eight long passages with almost no punctuation').replace('is the most famous passage in modernist fiction','is among the best-known passages in modernist fiction')
D['cast'][2]['description']='Hun blev født som Marion Tweedy i Gibraltar, datter af Lunita Laredo og den irske soldat major Tweedy. Nu er hun treogtredive år og professionel sanger i Dublin. Hun har tilbragt eftermiddagen i seng med sin koncertarrangør Blazes Boylan. Hun er sanselig, skarp, morsom og intelligent på en måde, de fleste af bogens mænd overser. Hendes afsluttende monolog består af otte lange afsnit med næsten ingen tegnsætning. Tankerne bevæger sig mellem erindringer, lyst og ægteskab og giver hende romanens sidste ord.'
E['cast'][3]['description']=E['cast'][3]['description'].replace('while shaving on the parapet','as he prepares to shave on the tower').replace('He has called Stephen\'s mother "beastly dead." Stephen will not forgive him.','Stephen cannot forgive his flippant remark about his mother being dead.')
D['cast'][3]['description']='En medicinstuderende, der deler Martellotårnet ved Sandycove med Stephen og en engelsk gæst. Han indleder romanen med en latinsk parodi på messen, mens han gør sig klar til at barbere sig. Han er begavet, hånlig og sjofel og bruger sin humor til at undgå alvoren, også sorgen. Stephen kan ikke tilgive hans respektløse bemærkning om sin døde mor. Joyce brugte sin virkelige ven og rival Oliver St. John Gogarty som forbillede.'
E['cast'][4]['description']=E['cast'][4]['description'].replace('he watches a clock cross four o\'clock and keeps walking','his awareness of the appointment follows him through the day').replace('picking up a basket of fruit on Grafton Street','ordering a basket of fruit on Grafton Street').replace('every scene Bloom navigates between morning and night','Bloom’s thoughts through the day').replace('and uninteresting on the inside','and largely seen from the outside')
D['cast'][4]['description']='En levemand fra Dublin, koncertarrangør og Mollys elsker. Bloom ved, at Boylan har en aftale i hans hjem klokken fire, og tanken følger ham gennem dagen. Vi ser blandt andet Boylan bestille en frugtkurv på Grafton street og køre i droske, men hans betydning mærkes også i de scener, hvor han er fraværende. Han er selvsikker og seksuelt direkte. Hvor vi følger Blooms tanker tæt, ser vi hovedsagelig Boylan udefra.'
D['cast'][5]['description']='En ung kvinde fra Dublin, som halter lidt. Hun sidder på Sandymount Strand i tusmørket, mens Bloom ser på hende under et fyrværkeri. Hendes episode, Nausikaa, låner sin stil fra den sene victorianske tids dameblade og romantiske fortællinger, før perspektivet skifter til Bloom. De velkendte vendinger former hendes forestillinger om kærlighed og om sig selv. Skiftet mellem de to synsvinkler gør deres møde til et af romanens tydeligste stileksperimenter.'
D['angleCards'][0]['title']='Fortælleformen, episode for episode.'
D['angleCards'][0]['text']='Joyce skifter mellem indre monolog, spørgsmål og svar, avisparodi og musikalske sproglege. Jeg vil læse Ulysses som et laboratorium og se, hvordan stilvalgene ændrer min forståelse af de samme personer.'
D['angleCards'][1]['text']='Homers helt var snu, modig og enestående. Joyces helt køber en svinenyre. Jeg vil følge forbindelserne til Homer og undersøge, hvad der sker, når et epos bliver til hverdag, og om Blooms anstændighed kan forstås som heltemod.'
D['angleCards'][2]['text']='Stephen Dedalus er ung, begavet og åndeligt hjemløs. Leopold Bloom mistede sin søn Rudy som spæd og bærer stadig på sorgen. Deres veje mødes den 16. juni, men mødet giver ingen enkel forløsning. Jeg vil følge det, der opstår mellem dem.'
E['whyItMatters'][0]['body']=E['whyItMatters'][0]['body'].replace('The first three are relatively conventional interior monologue, easing the reader in.','The first three move between external narration and Stephen’s thoughts; the third, Proteus, is already demanding.').replace('the entire history of English prose styles','a succession of English prose styles').replace('Every later novel that mixes techniques across its chapters is in this novel\'s debt.','Its shifts of technique have become an influential model for later fiction.')
D['whyItMatters'][0]['body']='Joyce delte Ulysses i atten episoder med forskellige fortælleformer. De første tre veksler mellem fortælling udefra og Stephens tanker; allerede den tredje, Proteus, kan være krævende at læse. Aiolos brydes op af avisoverskrifter. Solens okser efterligner en række historiske engelske stilarter, fra angelsaksisk klang til senere tiders prosa og slang. Kirke er et hallucinatorisk skuespil med sceneanvisninger og umulige sceneskift. Ithaka består af spørgsmål og svar, der beskriver selv vandet i Blooms kedel og hans vandladning med pedantisk præcision. Formerne viser forskellige sider af den samme by og dens mennesker. Disse skift har inspireret mange senere romanforfattere.'
E['whyItMatters'][1]['body']=E['whyItMatters'][1]['body'].replace('buys a bar of lemon soap and forgets to pay for it','takes a bar of lemon soap with a promise to pay later').replace('Most modern fiction has worked from this premise since. The premise is the modern novel\'s permission to take seriously the lives that epic could not.','That attention to ordinary experience has helped shape later fiction.')
D['whyItMatters'][1]['body']='Homers Odysseus er en konge og kriger, der overlever den trojanske krig og skyller nøgen op på faiakernes kyst. Joyces Odysseus sælger annoncer, mens hans kone går i seng med en anden. Han tager et stykke citronsæbe med sig og lover at betale senere, spiser en gorgonzolasandwich hos Davy Byrne og onanerer på Sandymount Strand, mens han ser på en fremmed under et fyrværkeri. Om natten går han hjem og tilbyder den unge digter en seng. Stephen siger nej. Vandring, hjemkomst, genkendelse og gæstfrihed forbinder de to fortællinger. Romanen lader os finde heltemod i omsorg og opmærksomhed på en ganske almindelig dag, en tilgang som har været vigtig for senere litteratur.'
E['whyItMatters'][2]['body']=E['whyItMatters'][2]['body'].replace('with the most-quoted affirmation in English-language fiction','with one of the best-known affirmations in English-language fiction')
D['whyItMatters'][2]['body']='Molly Blooms afsluttende kapitel, Penelope, består af otte lange afsnit med næsten ingen tegnsætning. Hun ligger vågen ved siden af Bloom i de små timer. Tankerne glider mellem kropslige fornemmelser og minder om ægteskabet, eftermiddagens elsker, sønnen der døde som spæd, og barndommen i Gibraltar. Til sidst husker hun den eftermiddag på Howth head, hvor Bloom friede, og hun sagde ja. Kapitlets sidste ord, »ja sagde jeg ja jeg vil Ja«, er blevet berømte. Formen giver os en bevidsthed, hvor tanke og sansning flyder ind i hinanden, og hvor en ny erindring kan afløse den forrige uden varsel.'
D['acclaim'][0]['quote']='Jeg anser denne bog for det vigtigste udtryk, vores tid har fundet.'
for lang,doc in [('en',E),('da',D)]:
 wr('onboarding-'+lang+'.json',doc)
 before=rd('source-onboarding-'+lang+'.json');changes=[]
 def diff(a,b,path=[]):
  if isinstance(a,dict):
   for k in a:diff(a[k],b[k],path+[k])
  elif isinstance(a,list):
   for i in range(len(a)):diff(a[i],b[i],path+[i])
  elif a!=b:changes.append({'path':path,'before':a,'after':b})
 diff(before,doc);wr('working-guide-'+lang+'-changes.json',changes)
wr('guide-review-notes.json',{'status':'draft-revised-native-review-pending','changes':['US ban lifted in 1933, first authorised US edition 1934; corrected conflation.','Removed former seminarian and unsupported year in Paris; Stephen rejected priesthood.','Molly mother named without asserting disputed ethnicity.','Removed schema organ for every episode, easy Proteus, definitive page count, exaggerated universal influence and superlatives.','Corrected Grafton purchase to order, soap purchase credit not forgotten payment, beastly dead mistranslation, sex euphemism ambiguity.','Both complete guides read and Danish prose polished; exact opening sample aligned to edition.'], 'references':['https://online-exhibitions.library.columbia.edu/exhibits/show/jewels/themes/literature/213','https://www.nationaltrustcollections.org.uk/article/100-years-of-ulysses-by-james-joyce','https://modernistcommons.ca/islandora/object/yale:66','Saved original text episodes 1, 3, 5, 10, 17, 18; Stephen vocation in A Portrait of the Artist as a Young Man.'], 'outstanding':['Verify exact Eliot quotation from 1923 scan (current retained English wording may be paraphrased).','Native final read pending.']})
